def main():
    import sys
    s = sys.stdin.readline().strip()
    n = len(s)

    def longest_palindromic_prefix(t):
        l = len(t)
        for i in range(l, 0, -1):
            prefix = t[:i]
            if prefix == prefix[::-1]:
                return prefix
        return ""

    def longest_palindromic_suffix(t):
        l = len(t)
        for i in range(l, 0, -1):
            suffix = t[-i:]
            if suffix == suffix[::-1]:
                return suffix
        return ""

    lps = longest_palindromic_suffix(s)
    lpp = longest_palindromic_prefix(s)
    omeric = lps + lpp

    freq = []
    for i in range(1, len(omeric)+1):
        prefix = omeric[:i]
        count = 0
        m = len(omeric)
        for j in range(m - i + 1):
            if omeric[j:j+i] == prefix:
                count += 1
        freq.append(str(count))

    print(omeric)
    print(' '.join(freq))

main()
